const items = $input.all();

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

return items.map((item) => {
  const numKeywords = 5;

  const fullText = String(item.json.ChunkText ?? '').trim();

  // Exakt der Text, der später auch an Ollama geht
  const promptText = fullText
    .slice(0, 12000)
    .replace(/\.{4,}/g, '...')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();

  const words =
    promptText.match(
      /\b[\p{L}\p{N}][\p{L}\p{N}\p{M}\-–/]*\b/gu
    ) ?? [];

  const promptWordCount = words.length;

  const summaryMinLength = clamp(
    Math.round(promptWordCount * 0.15),
    100,
    200
  );

  const summaryMaxLength = clamp(
    Math.round(promptWordCount * 0.25),
    Math.max(summaryMinLength + 50, 130),
    350
  );

  const lengthCorrectionFactor = 1.5;

  const promptSummaryMinLength = Math.ceil(
    summaryMinLength * lengthCorrectionFactor
  );

  const promptSummaryMaxLength = Math.ceil(
    summaryMaxLength * lengthCorrectionFactor
  );

  const numPredict = clamp(
    Math.ceil(promptSummaryMaxLength * 2.2 + 300),
    800,
    2200
  );

  return {
    json: {
      ...item.json,

      PromptText: promptText,

      numKeywords,
      promptWordCount,

      summaryMinLength,
      summaryMaxLength,

      promptSummaryMinLength,
      promptSummaryMaxLength,

      lengthCorrectionFactor,
      numPredict
    }
  };
});

const responseItems = $input.all();
const sourceItems = $("Code - calculate SummaryLength").all();

function countWords(text) {
  return (
    String(text).match(
      /\b[\p{L}\p{N}][\p{L}\p{N}\p{M}\-–/]*\b/gu
    ) ?? []
  ).length;
}

function cleanString(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ");
}

return responseItems.map((item, index) => {
  const source = sourceItems[index]?.json ?? {};

  let rawContent = item.json.message?.content;

  if (typeof rawContent !== "string" || rawContent.trim() === "") {
    throw new Error(
      `Item ${index}: Ollama hat kein verwertbares message.content geliefert.`
    );
  }

  rawContent = rawContent
    .trim()
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(rawContent);
  } catch (error) {
    throw new Error(
      `Item ${index}: Ungültiges JSON von Ollama: ${error.message}`
    );
  }

  const title = cleanString(parsed.title);

  const keywords = Array.isArray(parsed.keywords)
    ? parsed.keywords.map(cleanString).filter(Boolean)
    : [];

  const summary = String(parsed.summary ?? "").trim();

  if (!title) {
    throw new Error(`Item ${index}: Der Titel fehlt.`);
  }

  if (keywords.length !== source.numKeywords) {
    throw new Error(
      `Item ${index}: ${keywords.length} statt genau ${source.numKeywords} Keywords erhalten.`
    );
  }

  const normalizedKeywords = keywords.map((keyword) =>
    keyword.toLocaleLowerCase("de-DE")
  );

  if (new Set(normalizedKeywords).size !== source.numKeywords) {
    throw new Error(`Item ${index}: Die Keywords enthalten Dubletten.`);
  }

  if (!summary) {
    throw new Error(`Item ${index}: Die Zusammenfassung fehlt.`);
  }

  const summaryWordCount = countWords(summary);
  const summaryMinLength = Number(source.summaryMinLength ?? 0);
  const summaryMaxLength = Number(source.summaryMaxLength ?? 999999);

  const validationPassed =
    summaryWordCount >= summaryMinLength &&
    summaryWordCount <= summaryMaxLength;

  return {
    json: {
      ...source,

      TextTitel: title,
      TextKeywords: keywords.join(", "),
      TextKeywordsJSON: JSON.stringify(keywords),
      TextZusammenfassung: summary,

      summaryWordCount,
      validationPassed,
      validationError: validationPassed
        ? null
        : `Zusammenfassung enthält ${summaryWordCount} Wörter; erwartet wurden ${summaryMinLength} bis ${summaryMaxLength}.`,

      ollamaModel: item.json.model ?? null,
      ollamaDoneReason: item.json.done_reason ?? null,
      ollamaPromptTokens: item.json.prompt_eval_count ?? null,
      ollamaOutputTokens: item.json.eval_count ?? null,
      ollamaTotalDurationNs: item.json.total_duration ?? null
    },
    pairedItem: {
      item: index
    }
  };
});

